import java.util.*;

class Trie {
    private final List<String> words = new ArrayList<>();

    public Trie() {
    }

    public void insert(String word) {
        words.add(word);
    }

    public boolean search(String word) {
        for (String w : words) {
            if (w.equals(word)) return true;
        }
        return false;
    }

    public boolean startsWith(String prefix) {
        for (String w : words) {
            if (w.startsWith(prefix)) return true;
        }
        return false;
    }
}

import java.util.*;

class Trie {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isEnd;
    }

    private final TrieNode root = new TrieNode();

    public Trie() {
    }

    public void insert(String word) {
        TrieNode node = root;
        for (int i = 0; i < word.length(); i++) {
            int idx = word.charAt(i) - 97;
            if (node.children[idx] == null) node.children[idx] = new TrieNode();
            node = node.children[idx];
        }
        node.isEnd = true;
    }

    private TrieNode walk(String s) {
        TrieNode node = root;
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 97;
            if (node.children[idx] == null) return null;
            node = node.children[idx];
        }
        return node;
    }

    public boolean search(String word) {
        TrieNode node = walk(word);
        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return walk(prefix) != null;
    }
}

import java.util.*;

class Trie {
    private final List<Map<Character, Integer>> nodes = new ArrayList<>();
    private final List<Boolean> ends = new ArrayList<>();

    public Trie() {
        nodes.add(new HashMap<>());
        ends.add(false);
    }

    public void insert(String word) {
        int id = 0;
        for (int i = 0; i < word.length(); i++) {
            char ch = word.charAt(i);
            Map<Character, Integer> child = nodes.get(id);
            Integer next = child.get(ch);
            if (next == null) {
                next = nodes.size();
                child.put(ch, next);
                nodes.add(new HashMap<>());
                ends.add(false);
            }
            id = next;
        }
        ends.set(id, true);
    }

    private int walk(String s) {
        int id = 0;
        for (int i = 0; i < s.length(); i++) {
            Integer next = nodes.get(id).get(s.charAt(i));
            if (next == null) return -1;
            id = next;
        }
        return id;
    }

    public boolean search(String word) {
        int id = walk(word);
        return id != -1 && ends.get(id);
    }

    public boolean startsWith(String prefix) {
        return walk(prefix) != -1;
    }
}
